import * as fs from 'fs';
import * as path from 'path';
export class ReportGenerator {
    static generate(evidenceGraph, outputPath, runId) {
        const snapshot = evidenceGraph.snapshot(runId);
        let markdown = `# ArchMind AI Analysis Report\n\n`;
        markdown += `> Generated on ${new Date().toUTCString()}\n\n`;
        // Extract metadata
        const repoNode = snapshot.nodes.find(n => n.kind === 'metadata:repository');
        if (repoNode) {
            markdown += `## Repository Information\n`;
            const metadata = repoNode.label;
            markdown += `- **Repository**: \`${metadata}\`\n\n`;
        }
        // Extract architecture
        const archNode = snapshot.nodes.find(n => n.kind === 'ArchitectureDetected');
        if (archNode) {
            markdown += `## Architecture Detection\n`;
            markdown += `- **Primary Pattern**: ${archNode.label}\n`;
            const boundaryNode = snapshot.nodes.find(n => n.kind === 'ModuleBoundaryDetected');
            if (boundaryNode) {
                markdown += `- **Domain Boundaries**: ${boundaryNode.label}\n`;
            }
            markdown += `\n`;
        }
        // Extract dependency health
        const depNode = snapshot.nodes.find(n => n.kind === 'analysis:dependency-health');
        if (depNode && depNode.value) {
            markdown += `## Dependency Health\n`;
            const val = depNode.value;
            markdown += `- **Health Score**: ${val.healthScore}/100\n`;
            if (val.unusedPackages?.length > 0) {
                markdown += `- **Unused Packages**: ${val.unusedPackages.join(', ')}\n`;
            }
            if (val.duplicateDependencies?.length > 0) {
                markdown += `- **Duplicate Dependencies**: ${val.duplicateDependencies.join(', ')}\n`;
            }
            if (val.risks?.length > 0) {
                markdown += `- **Risks identified**: ${val.risks.length}\n`;
            }
            markdown += `\n`;
        }
        // List all evidence
        markdown += `## Evidence Graph Summary\n`;
        markdown += `| Node ID | Kind | Label | Confidence |\n`;
        markdown += `|---------|------|-------|------------|\n`;
        for (const node of snapshot.nodes) {
            markdown += `| \`${node.id}\` | \`${node.kind}\` | ${this.#escape(node.label)} | ${(node.confidence.score * 100).toFixed(0)}% |\n`;
        }
        markdown += `\n\n---\n*Report generated by ArchMind AI v0.1.0*\n`;
        fs.writeFileSync(path.resolve(process.cwd(), outputPath), markdown, 'utf8');
    }
    static #escape(str) {
        return str.replace(/\|/g, '\\|').replace(/\n/g, ' ');
    }
}
